import type { HTMLAttributes, ReactNode } from 'react';
import { Button } from './button';
import { Icon } from './icon';

export interface AiGhostRowProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onSelect'> {
  /** Name of the suggestion. It completes the button names ("Accept <name>"). */
  name: string;
  /** Summary of the suggestion, e.g. "Tartelette Framboise · 200". */
  children: ReactNode;
  onAccept: () => void;
  onEdit: () => void;
  onReject: () => void;
  busy?: boolean;
}

/** An AI-generated example, written as unconfirmed ("Generated by AI, review needed") until a person acts. */
export function AiGhostRow({ name, children, onAccept, onEdit, onReject, busy, className, ...rest }: AiGhostRowProps) {
  return (
    <div
      {...rest}
      className={['ai-row', className].filter(Boolean).join(' ')}
      role="group"
      aria-label={`AI suggestion: ${name}`}
      aria-busy={busy || undefined}
    >
      <span className="ai-row-label">
        <Icon name="spark" size={14} />
        Generated by AI, review needed
      </span>
      <span className="ai-row-body">{children}</span>
      <span className="ai-row-actions">
        <Button type="button" variant="primary" size="sm" disabled={busy} onClick={onAccept}>
          Accept{' '}
          <span className="sr-only">{name}</span>
        </Button>
        <Button type="button" variant="secondary" size="sm" disabled={busy} onClick={onEdit}>
          Edit{' '}
          <span className="sr-only">{name}</span>
        </Button>
        <Button type="button" variant="ghost" size="sm" disabled={busy} onClick={onReject}>
          Reject{' '}
          <span className="sr-only">{name}</span>
        </Button>
      </span>
    </div>
  );
}
